/// What a name used in `file` is bound to, for deciding whether it may take a builtin meaning: a project-local
/// `ReactNode` or `Partial`, or one imported from some other package, is that declaration, not React's or TypeScript's.
#[derive(Debug, PartialEq, Eq)]
pub(super) enum NameBinding {
    /// Declared in `file`.
    Local,
    /// Imported in `file` (for a qualified name, its namespace is) from this specifier.
    Imported(String),
    /// Neither: a global, such as TypeScript's lib types or React's ambient namespace.
    Unbound,
}

pub(super) fn name_binding(name: &str, file: &Utf8Path, ctx: &ResolutionContext) -> NameBinding {
    deps::record(file);
    let head = name.split('.').next().unwrap_or(name);
    if head == name && ctx.named_types.is_declared_at(file, name) {
        return NameBinding::Local;
    }
    match ctx.import_map.find_import(file, head) {
        Some(import) => NameBinding::Imported(import.specifier.clone()),
        None => NameBinding::Unbound,
    }
}

/// Whether `name` in `file` can be React's own type: imported from React, or not bound at all.
pub(super) fn may_be_react_builtin(name: &str, file: &Utf8Path, ctx: &ResolutionContext) -> bool {
    match name_binding(name, file, ctx) {
        NameBinding::Local => false,
        NameBinding::Imported(specifier) => {
            specifier == "react" || specifier.starts_with("react/") || specifier == "@types/react"
        }
        NameBinding::Unbound => true,
    }
}

/// Whether `name` in `file` is a type React declares (`UIEventHandler`, `Key`, `AriaRole`, …) that no builtin list names:
/// it is bound to React, or to nothing, and React's own declarations have it. Such a reference is React's type, not an
/// unresolvable one.
pub(super) fn declared_by_react(name: &str, canonical_name: &str, file: &Utf8Path, ctx: &ResolutionContext) -> bool {
        for export in &data.exports {
            match export {
                LexedExport::ReExportNamed { local_name, source_name, source_specifier, .. } if local_name == head => {
                    // An explicit export shadows a wildcard one, so a hop that cannot be resolved leaves the name unanswered
                    // rather than to a later `export *`; `unresolved_cause` names the hop.
                    let Ok(target) = self.resolve(module, source_specifier) else { return None };
                    let next = match rest {
                        Some(rest) => format!("{source_name}.{rest}"),
                        None => source_name.clone(),
                    };
                    return self.find_export_in(&target, &next, visited, cut);
                }
                LexedExport::ReExportNamespace { namespace, source_specifier } if namespace == head => {
                    let Ok(target) = self.resolve(module, source_specifier) else { return None };
                    return self.find_export_in(&target, rest?, visited, cut);
                }
                // `export { DialogContent as Content }`, the way bundled typings (Radix's) name their parts.
                LexedExport::LocalDeclaration { name: exported, declared_as: Some(local), .. }
                    if exported == head && declares(&data, module, local) =>
                {
                    let name = match rest {
                        Some(rest) => format!("{local}.{rest}"),
                        None => local.clone(),
                    };
                    return Some((module.to_owned(), CompactString::from(name)));
                }
                _ => {}
            }
        }
        // A local export can name an imported binding (`import Image from './Image'; export default Image`).
        if let Some(local) = data.exports.iter().find_map(|export| match export {
            LexedExport::LocalDeclaration { name: exported, declared_as, .. } if exported == head => {
                Some(declared_as.as_deref().unwrap_or(head))
            }
            LexedExport::LocalDeclaration { .. }
            | LexedExport::ReExportNamed { .. }
            | LexedExport::ReExportAll { .. }
            | LexedExport::ReExportNamespace { .. } => None,
        }) {
            let reference = rest.map_or_else(|| local.to_owned(), |rest| format!("{local}.{rest}"));
            if let Some(demand) = imported_demand(module, &data.imports, &reference) {
                let target = self.resolve(module, &demand.specifier).ok()?;
                return self.find_export_in(&target, &demand.name, visited, cut);
            }
        }
        if head == "default" {
            return None;
        }
        for export in &data.exports {
            if let LexedExport::ReExportAll { source_specifier, .. } = export {
                let Ok(target) = self.resolve(module, source_specifier) else { continue };
                if let Some(found) = self.find_export_in(&target, name, visited, cut) {
                    return Some(found);
                }
            }
        }
        None
    }

    /// Runs `demand` on the scope, recording a panic as a diagnostic instead of letting it end the whole load.
    fn spawn_demand<'s>(&'s self, scope: &rayon::Scope<'s>, demand: Demand) {
        scope.spawn(move |scope| {
            let label = format!("dependency demand {}#{}", demand.specifier, demand.name);
            if let Err(panic) = crate::panic_guard::contain_panic(&label, || self.demand(scope, demand)) {
                self.panics.lock().unwrap_or_else(std::sync::PoisonError::into_inner).push(panic);
            }
        });
    }

    fn demand<'s>(&'s self, scope: &rayon::Scope<'s>, demand: Demand) {
        #[cfg(test)]
        assert!(&*demand.name != DEMAND_PANIC_TEST_NAME, "injected panic");
        let key = demand.key();
        if self.parent.is_some_and(|parent| parent.has_demand(&key)) || !self.demands.insert(key.clone()) {
            return;
        }
        if demand.name.is_empty() {
            self.module_demand(scope, &demand);
            return;
        }
        let module = match self.resolve(&demand.from, &demand.specifier) {
            Ok(module) => module,
            Err(reason) => {
                if !demand.name.is_empty() {
                    self.unresolved.insert(key, reason);
                }
                return;
            }
        };
        if self.in_project(&module) {
            return;
        }
        if Self::is_react(&module) {
            // `@types/react` declares its exports inside `declare namespace React` (`export = React`).
            let qualified = CompactString::from(format!("React.{}", demand.name));
            if self.parse(&module).is_some_and(|data| declares(&data, &module, &qualified)) {
                self.load_declaration(scope, module, qualified);
            }
            return;
        }
        match self.find_export(&module, &demand.name) {
            Some((file, name)) => self.load_declaration(scope, file, name),
            None => {
                let cause = self.unresolved_cause(&module, &demand.name).unwrap_or(Unresolved::NotExported);
                self.unresolved.insert(key, cause);
            }
        }
    }

    /// Why a name `module` seems not to export was not found: a re-export hop on the way to it that cannot be
    /// resolved. A named or namespace hop for the name is the cause outright; an unresolvable `export *` only could
    /// have held it, so it is reported when nothing else explains the miss. `None` means every hop resolved.
    fn unresolved_cause(&self, module: &Utf8Path, name: &str) -> Option<Unresolved> {
        let mut visited = FxHashSet::default();
        let mut star = None;
        self.unresolved_cause_in(module, name, &mut visited, &mut star).or(star)
    }

    fn unresolved_cause_in(
        &self,
        module: &Utf8Path,
        name: &str,
        visited: &mut FxHashSet<(PathKey, CompactString)>,
        star: &mut Option<Unresolved>,
    ) -> Option<Unresolved> {
        if !visited.insert((PathKey::from(module), CompactString::from(name))) {
            return None;
        }
        let data = self.parse(module)?;
        let (head, rest) = match name.split_once('.') {
            Some((head, rest)) => (head, Some(rest)),
            None => (name, None),
        };
        for export in &data.exports {
            let (specifier, next) = match export {
                LexedExport::ReExportNamed { local_name, source_name, source_specifier, .. } if local_name == head => {
                    let next = rest.map_or_else(|| source_name.clone(), |rest| format!("{source_name}.{rest}"));
                    (source_specifier, next)
                }
                LexedExport::ReExportNamespace { namespace, source_specifier } if namespace == head => {
                    (source_specifier, rest?.to_owned())
                }
                LexedExport::ReExportAll { source_specifier, .. } => (source_specifier, name.to_owned()),
                _ => continue,
            };
            let star_hop = matches!(export, LexedExport::ReExportAll { .. });
            match self.resolve(module, specifier) {
                Err(cause) if star_hop => {
                    star.get_or_insert(cause);
                }
                Err(cause) => return Some(cause),
                Ok(target) => {
                    if let Some(cause) = self.unresolved_cause_in(&target, &next, visited, star) {
                        return Some(cause);
                    }
                }
            }
        }
        None
    }

